package com.imr.reqestra.presentation.i18n

import androidx.compose.runtime.Composable
import androidx.compose.runtime.staticCompositionLocalOf

data class LanguageOption(val code: String, val name: String)

/** Device language is selected by default; a manual override is stored locally. */
object ReqestraLanguages {
    val supported = listOf(
        LanguageOption("en", "English"),
        LanguageOption("es", "Español"),
        LanguageOption("ru", "Русский"),
        LanguageOption("zh", "简体中文"),
        LanguageOption("pt", "Português"),
        LanguageOption("fr", "Français"),
    )

    fun normalize(tag: String?): String {
        val code = tag.orEmpty().lowercase(java.util.Locale.ROOT).substringBefore('-').substringBefore('_')
        return if (supported.any { it.code == code }) code else "en"
    }

