    fun translate(source: String, language: String): String {
        val code = normalize(language)
        if (code == "es") return source
        val values = catalog[source] ?: return source
        val index = when (code) {
            "ru" -> 1
            "zh" -> 2
            "pt" -> 3
            "fr" -> 4
            else -> 0
        }
        return values[index].ifBlank { values[0] }
    }
}

val LocalReqestraLanguage = staticCompositionLocalOf { "en" }

/** Locale-aware UI text for Compose. No network calls or remote translation. */
@Composable
fun tr(spanishSource: String): String =
    ReqestraLanguages.translate(spanishSource, LocalReqestraLanguage.current)
